/*
----- Optimized DESSINS Géométriques ----- 
Original by Patt Vira
Optimized for Patchies
----------------------------------------
*/

let DESSIN = "264";
let size = 10;
let zoom = 0.5;
let speed = 0.03;

// Pre-allocated variables for performance
let cols, rows, maxR2, gridCount;
let gridX, gridY, gridMul;
let formula;

setPortCount(0, 0);

function setup() {
  createCanvas(300, 300);
  pixelDensity(2); // High resolution maintained as per original
  colorMode(HSB, 360, 100, 100);
  noDrag();

  cols = Math.floor(width / size);
  rows = Math.floor(height / size);
  maxR2 = (size / 3) * 2; // Pre-calculate diameter multiplier
  gridCount = cols * rows;

  // Using typed arrays for significantly faster access than objects
  gridX = new Float32Array(gridCount);
  gridY = new Float32Array(gridCount);
  gridMul = new Float32Array(gridCount);

  // Determine the formula once at setup to avoid branching inside the draw loop
  if (DESSIN === "251") {
    formula = (m, z) => m * z;
  } else {
    formula = (m, z) => (m * z) % 1;
  }

  // Pre-calculate all static grid coordinates and multipliers
  let index = 0;
  for (let i = 0; i < cols; i++) {
    let x = i * size + size / 2;
    let xx = map(i, 0, cols - 1, -1, 1);
    for (let j = 0; j < rows; j++) {
      gridX[index] = x;
      gridY[index] = j * size + size / 2;
      gridMul[index] = xx * map(j, 0, rows - 1, -1, 1);
      index++;
    }
  }
}

function draw() {
  background(220, 50, 30);

  // Local cache of global variables for tighter loop performance
  const z = zoom;
  const count = gridCount;
  const r2 = maxR2;
  const fAction = formula;

  for (let i = 0; i < count; i++) {
    // Inline computation logic
    const F = fAction(gridMul[i], z);
    const diam = F * r2;

    // Hue calculation (120 to 220 based on F)
    const h = 120 + F * 100;

    // P5 drawing calls
    stroke(h, 80, 50); // b - 50 = 50
    fill(h, 80, 100);   // s = 80, b = 100

    ellipse(gridX[i], gridY[i], diam, diam);
  }

  zoom += speed;
}

/*
