import { Tile, size, hoverDistance } from 'tile.js'

let cols, rows;
let tiles = [];

noDrag()
setPortCount(0, 0)

function setup() {
  createCanvas(300, 300);
  rectMode(CENTER);
  cols = width/size;
  rows = height/size;

  for (let i=0; i<cols; i++) {
    tiles[i] = [];
    for (let j=0; j<rows; j++) {
      let x = i*size + size/2;
      let y = j*size + size/2;
      tiles[i][j] = new Tile(x, y);
    }
  }

}

function draw() {
  background(255, 248, 230);

  for (let i=0; i<cols; i++) {
    for (let j=0; j<rows; j++) {
      tiles[i][j].update();
      tiles[i][j].display();
    }
  }
}

// @lib tile.js

export const hoverDistance = 15;
export const size = 20;

export class Tile {
  constructor(x, y) {
    this.x = x;
    this.y = y; 
    this.type = 1; // Set to floor(random(2)) to randomly choose a starting type 
    this.angle = 0;
    this.amt = 0;
    this.startingAngle = 0;
    this.isAnimating = false;

    const colors = [
      color(255, 94, 98),    
      color(255, 165, 0),    
      color(255, 221, 102),  
      color(102, 204, 153),  
      color(0, 153, 204),    
      color(153, 102, 255),  
    ];

    this.c = colors[floor(random(colors.length))];
  }

  update() {    
    let distance = dist(mouseX, mouseY, this.x, this.y);
    if (distance < hoverDistance && !this.isAimating) {
      this.isAnimating = true;
      this.rotAngle = floor(random(1, 4)) * PI/2; // Randomly choose how much to rotate in an increment of PI/2 (90 degrees)
    }
    return

    if (this.isAnimating) {
      this.amt += 0.01;
      if (this.amt > 1) {
        this.amt = 0;
        this.startingAngle += this.rotAngle;
        this.isAnimating = false;
      }
    }

    this.angle = this.startingAngle + easeInOutQuad(this.amt) * this.rotAngle;
  }

  display() {
    push();
    translate(this.x, this.y);
    rotate(this.angle);

    noStroke();
    fill(0, 105, 130);
    rect(0, 0, size, size);

    strokeWeight(4);
    stroke(this.c);

    if (this.type == 0) {
      arc(-size/2, -size/2, size, size, 0, PI/2);
      arc(size/2, size/2, size, size, PI, 3*PI/2);
    } else {
      arc(-size/2, size/2, size, size, 3*PI/2, 0);
      arc(size/2, -size/2, size, size, PI/2, PI);
    }
    pop();
  }
}
